{'code': "from qgis.PyQt.QtWidgets import QAction, QMenu
from qgis.core import QgsApplication
mw = iface.mainWindow()
target = mw.findChild(QAction, 'mProcessingUserMenu_native:selectbylocation')
found = []
def walk(m, path):
    for act in m.actions():
        if act is target:
            found.append(path)
        sub = act.menu()
        if sub:
            walk(sub, path + [sub.title()])
for act in mw.menuBar().actions():
    sub = act.menu()
    if sub:
        walk(sub, [sub.title()])
alg = QgsApplication.processingRegistry().algorithmById('native:selectbylocation')
toolbar = mw.findChild(QAction, 'mProcessingAlg_native:selectbylocation')
result = {
    'menu_path': found,
    'alg_found': alg is not None,
    'alg_name': alg.displayName() if alg else None,
    'toolbar_action_enabled': toolbar.isEnabled() if toolbar else None,
    'toolbar_parent': type(toolbar.parent()).__name__ if toolbar else None,
}"}
